"""Closed alternating-bank regeneration and cold-hardware thermal-mass frontier."""
from pathlib import Path
import json,math,hashlib
P=Path(__file__).resolve().parent
j=json.loads((P/'joint-ports.json').read_text());p=json.loads((P/'pumping-interfaces.json').read_text());i=json.loads((P/'inputs.json').read_text());r=j['representative_interface'];area=r['required_active_panel_area_fraction_Hgetter_Hecryo'][1];A=4*math.pi*i['R_m']**2;q=i['plant']['helium_per_s']*i['atomic_mass_kg']['he4']/A
cap=p['helium_sorber_capacity_scenarios'][0]['He_capacity_kg_m2'];rows=[]
for period in [600,3600,14400]:
 for CA in [100,1000,10000]:
  warm=area*CA*(85-5)/period
  rev=area*CA*(200*math.log(85/5)-(85-5))/period
  rows.append({'active_bank_capture_period_s':period,'alternating_isolated_bank_count':2,'cycling_heat_capacity_J_per_active_m2_K':CA,'constant_heat_capacity_scope':'Chosen integrated thermal-mass comparison over5–85K. Actual temperature-dependent solid heat capacity and adsorption heat should replace it.','He_load_kg_per_active_m2':q*period/area,'fraction_of_Day_low_load_graph_capacity':q*period/(area*cap),'regeneration_heating_W_per_wall_m2':warm,'reversible_cooldown_work_W_per_wall_m2':rev,'electric_cooldown_work_W_per_wall_m2_at_etaCarnot0p5':rev/.5,'thermal_source_rule':'Regeneration heat can be supplied from the200K waste reservoir. In that case its removal and later return cancel in the whole-station cold balance; only refrigeration work is an extra electrical load. If electrical heating is chosen instead, add the separately listed regeneration-heating power too. Regenerated He is isolated and compressed into product storage.'})
representative=next(x for x in rows if x['active_bank_capture_period_s']==3600 and x['cycling_heat_capacity_J_per_active_m2_K']==1000)
out={'family':i['family'],'representative':representative,'rows':rows,'maximum_period_at_reference_graph_load_s':area*cap/q,'installed_panel_mass_sensitivity_kg_per_wall_m2':[{'hardware_kg_per_panel_m2':x,'two_bank_He_mass':2*area*x} for x in [1,10,100]],'scope':['No loaded cryopanel speed or regeneration lifetime is claimed by this thermal-mass exercise. The reference load is a low-load graph scale, not ultimate capacity.','Two isolated banks permit one to capture while the other releases gas into a closed product manifold. Valves and thermal switches must isolate the warm bank from the cavity-facing path.','The assumed cycling heat capacity does not determine total installed mass; noncycling structure can remain cold.','Gas sensible cooling, surface adsorption heat, valves, conduction, supports and refrigerator hardware are separate named requirements.'],'source_sha256':{f:hashlib.sha256((P/f).read_bytes()).hexdigest() for f in ['joint-ports.json','pumping-interfaces.json','inputs.json']},'code_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}
(P/'regeneration.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(representative,indent=2))
